-- Grape notes, open points W1 and W2 (product owner, 2026-11-23: "Voer alle
-- voorstellen uit"). W1: rules from an official specification, each sentence
-- trimmed to what the specification says. W2: fields with two good sources,
-- kept only where a checking pass confirmed two independent organisations,
-- trimmed to what both support. 67 fields, filled only where still empty;
-- the file stops as a whole if any was no longer empty. local_note is then
-- rewritten for builds up to 1.9.0 (48). Sources per row: w_applied.csv.
begin;
create temp table w_hit (region_id uuid, grape_id uuid) on commit drop;
with u as (update public.wine_region_grapes set role_note = 'Allowed in Moselle Luxembourgeoise wines, and one of the few grapes permitted for its late harvest, straw and ice wines.' where region_id = 'd5ad7565-0bea-4217-9a0a-cbeb28a3f277' and grape_id = 'cc03411e-c3fa-4449-8b45-036f341e3633' and role_note is null returning region_id, grape_id) insert into w_hit select * from u;
